localimage_explain: "Образ открывается как обычный диск на этом компьютере, поэтому вы можете добавлять, заменять и удалять файлы внутри него — например, патчи — через Finder или Проводник, точно как на USB-накопителе. Изменения сохраняются прямо в файл образа. ps5upload никогда не пишет в образ сам; это делает ваша операционная система. Закончив, извлеките его здесь.",
localimage_filter: "Образы дисков",
