"pkglib.installAll.what": "Что такое «Установить всё»?",
"pkglib.installAll.whatBody": "«Установить всё» по очереди обрабатывает каждый готовый пакет: основная игра → обновления → DLC. Если у вас два обновления одной версии (или два конфликтующих DLC), с помощью флажка в каждой строке выберите, какое из них должна установить эта консоль — только одно на группу. Снимите флажок, чтобы пропустить группу целиком. Кнопка «Установить» в отдельной строке всегда устанавливает только этот пакет.",
ps5notif_clear: "Очистить все",
