"library_mount_modal_rw_body": "Смонтировав так, можно заменять файлы, добавлять DLC или применять патч бэкпорта — редактируйте монтирование в файловом браузере. Изменения записываются прямо в файл образа: неудачная правка может сделать игру незапускаемой, и отменить её нельзя, поэтому сначала скопируйте образ, если он важен. PS5 также может сама записывать сохранения в смонтированный образ.",
