"backport_summary": "Игра будет понижена до пары SDK FW 4, и будет установлен набор из {count} библиотек, поставляемый с {set}. Набор устанавливается целиком — смешивание библиотек из разных игр и приводит к тому, что бэкпорт не запускается.",
