"backport_verify_unpatched": "Для этой игры не сделан бэкпорт",
"backport_verify_unpatched_body": "Её eboot всё ещё содержит исходную версию SDK, поэтому она не может работать на этой прошивке, какие бы библиотеки ни были установлены — дело не в наборе библиотек. Выполните бэкпорт снова; если повторится, патч SDK не применяется.",
