"share.note.package": "Пакет передаётся на PS5 потоком и устанавливается. Заранее на PS5 ничего не копируется.",
"share.note.archive": "Архив откроется в разделе «Установить пакеты из архива», где перечислены пакеты внутри. Установите их оттуда.",
"share.note.copy": "Этот файл может прочитать только приложение, которое им поделилось, поэтому сначала он копируется в это приложение (до {limit}).",
