stop: "Остановить",
activity_description_v2: "Всё, что приложение делает и делало на ваших консолях: отправки, загрузки, установки и операции с файлами. Отсюда можно остановить или повторить любую из них. Хранятся последние 100, в том числе после перезапуска.",
fw_spoof_subtitle_v2: "Проверяет, не изменена ли версия прошивки, которую сообщает эта PS5, спуфинг-пейлоадом, чтобы вы знали настоящую версию до установки чего-то, что от неё зависит.",
health_subtitle_v2: "Проверяет, что PS5, это приложение и сеть между ними работают, подсказывает, что исправить, если нет, и измеряет скорость передачи файлов между ними.",
remotePlay_subtitle_v2: "Настройте эту PS5 для Remote Play и получите PIN-код, который связывает с ней приложение PS Remote Play.",
saves_description_v2: "Данные сохранений на PS5, по одной записи на игру. Сохраните резервную копию сохранений игры в .zip на этом компьютере и восстановите её позже.",
shell_description_v2: "Вводите команды, которые выполняются на PS5 в процессе помощника. Для опытных пользователей. Вывод ограничен 256 КБ на команду; стрелки вверх и вниз возвращают предыдущие команды.",
"arcpkg.links.go": "Скачать файлов: {count}",
