connection_payload_engine_unreachable: "Приложение не смогло связаться со своим движком на этом компьютере, поэтому не знает, запустился ли помощник на PS5. Это не проблема PS5: уведомление вверху окна объясняет причину и может перезапустить движок. Затем снова нажмите «Отправить помощника». ({error})",
"engine_problem.missing.fix": "Восстановите ps5upload-engine из карантина антивируса (или разрешите его) либо переустановите приложение.",
