"engine_problem.port.fix": "Нажмите «Перезапустить движок». Если не поможет, разрешите ps5upload-engine в брандмауэре или антивирусе и перезапустите приложение.",
"engine_problem.port.why": "Что-то занимает адрес движка ({url}), но не отвечает: другая программа на этом порту или защитная программа, блокирующая подключения к нему.",
"engine_problem.proxy.fix": "Отключите прокси или VPN для локальных адресов (127.0.0.1) либо запускайте приложение без переменной http_proxy / ALL_PROXY.",
"engine_problem.proxy.why": "Запросы к движку ушли на прокси, заданный на этом компьютере, а не к движку.",
"engine_problem.remote.fix": "Проверьте, что движок (контейнер Docker или другой компьютер) работает и доступен по этому адресу, или измените его в «Настройках».",
"engine_problem.remote.why": "Движок, который задан для этого приложения ({url}), не отвечает.",
"engine_problem.restart": "Перезапустить движок",
"engine_problem.slow.fix": "Нажмите «Перезапустить движок». Причиной может быть и брандмауэр или антивирус, фильтрующий локальные подключения: разрешите ps5upload-engine.",
"engine_problem.slow.why": "Движок работает, но не отвечает.",
"engine_problem.stopped.fix": "Нажмите «Перезапустить движок». Если он снова остановится, экран «Логи» покажет почему.",
"engine_problem.stopped.why": "Движок не работает: он остановился или так и не запустился.",
"engine_problem.title": "Приложение не может связаться со своим движком на этом компьютере",
"engine_problem.web.fix": "Проверьте, что сервер (контейнер Docker) работает, и перезагрузите эту страницу.",
"engine_problem.web.why": "Эта страница потеряла связь с сервером ps5upload, с которого она открыта.",
gate_engine_down_body_v2: "Этому экрану нужен движок приложения, а он не отвечает. Уведомление вверху окна объясняет причину и может его перезапустить.",
"profile.np.body": "PS5 начинает считать вошедший аккаунт подключённым к PlayStation Network, без обращения к Sony. Некоторые функции консоли доступны только для такого аккаунта, в том числе Remote Play. Используется np-fake-signin от earthonion, который загружается со страницы проекта при нажатии кнопки.",
"profile.np.confirm_title": "Выполнить вход для этого аккаунта?",
"profile.np.failed": "Вход не выполнен",
"profile.np.fetching": "Загрузка np-fake-signin…",
"profile.np.sending": "Отправка на PS5…",
"profile.np.sent": "np-fake-signin {version} выполнен на PS5. Перезапустите PS5, чтобы завершить; после этого аккаунт будет показан как вошедший, и можно включить Настройки > Система > Remote Play.",
"profile.np.sign_in": "Войти",
"profile.np.state_loading": "Чтение аккаунта…",
"profile.np.state_no_slot": "Ни один аккаунт выше не называется {user}, поэтому np-fake-signin остановится. Дайте аккаунту то же имя, что у вошедшего пользователя, или активируйте для него аккаунт.",
"profile.np.state_no_user": "На PS5 не выполнен вход ни одного пользователя. Войдите в нужный профиль и вернитесь.",
"profile.np.state_not_activated": "У {user} (аккаунт {slot}) ещё нет ID аккаунта. Сначала активируйте его в разделе «Аккаунты» выше.",
"profile.np.state_ready": "Готово: {user} (аккаунт {slot}) активирован.",
"profile.np.step_activate": "Аккаунту нужен ID. У аккаунта, связанного с PSN, он есть; иначе активируйте его в разделе «Аккаунты» выше (офлайн-активация).",
"profile.np.step_run": "Нажмите «Войти», когда на PS5 выполнен вход этого пользователя. Программа выполнится один раз и завершится.",
"profile.np.title": "Вход в PlayStation Network (офлайн)",
"fpkg.image.compress": "Сжать в .ffpfsc",
"fpkg.image.exfat_body": "Для игр, которые работают только как содержимое внешнего диска.",
"fpkg.image.exfat_choice": ".exfat",
"fpkg.image.ffpkg": ".ffpkg (UFS2), рекомендуется",
"fpkg.image.ffpkg_body": "То, что ShadowMount+ рекомендует для большинства игр.",
"fpkg.image.make": "Создать образ игры",
"fpkg.image.make_compressed": "Создать сжатый образ",
"fpkg.image.compress_body_v2": "Обычно на 40–60 % меньше, создаётся дольше и всегда монтируется только для чтения. Сжатие идёт во время записи, поэтому на диске есть только сжатый файл.",
"fpkg.image.level_fast_body": "Создаётся быстрее всего, чуть больше по размеру.",
"fpkg.image.level_balanced_body": "Почти такой же маленький и создаётся в несколько раз быстрее.",
"fpkg.image.level_smallest_body": "Самый маленький файл: второй, более сильный кодировщик обрабатывает каждый блок, поэтому это занимает в несколько раз больше времени.",
"fpkg.image.ffpfs": ".ffpfs (PFS), экспериментально",
"fpkg.image.ffpfs_body": "Экспериментальный формат в ShadowMount+ 1.7. Имена файлов должны быть только ASCII; имя самого образа ограничено 63 символами.",
