fs_send_dial_hint: "Оставьте пустым, чтобы использовать собственный адрес консоли. Для ps5-tailscale настройте локальный проброс на отправляющей консоли (её страница состояния: 127.0.0.1:19120 → другая консоль:9120) и укажите здесь 127.0.0.1:19120. Кто может отправлять, решают ключи консолей и одноразовый билет, а не адрес.",
