first_run_helper_only_hint: "Уже загружаете kstuff сами (автозагрузчик, etaHEN, elf-arsenal)? Отправьте только ps5upload — повторная загрузка kstuff добавляет ещё одну копию. Уже запущенные payload-ы в любом случае пропускаются.",
first_run_step_already_running: "уже запущен — повторно не отправлен",
