fs_bulk_cancel_copy: "Отменить копирование",
fs_bulk_cancel_copy_explainer: "Отмена: PS5 останавливает копирование и удаляет недокопированные файлы. Исходные файлы не затрагиваются.",
fs_bulk_cancel_copy_tooltip: "Отменить текущее копирование и пропустить остальное. Оригинал не затрагивается; недокопированные файлы удаляются.",
fs_finishing_files_left: "Осталось файлов: {left}",
fs_progress_eta: "осталось около {time}",
hardware_fan_lower_louder: "Это температура, которую старается удерживать управление вентиляторами консоли. Ниже — громче: под нагрузкой вентиляторы крутятся настолько сильно, насколько нужно, чтобы её удержать. Сохраняется после перезагрузки.",
"hardware_fan_above_stock": "Это теплее собственной настройки этой консоли, поэтому значение не применено.",
"hardware_fan_guard_failing": "ps5upload не смог удержать целевую температуру, поэтому вентилятором управляет сама консоль. Задайте цель снова, чтобы повторить.",
