hardware_fan_restored: "Собственная настройка вентиляторов консоли восстановлена.",
hardware_fan_stock: "Собственная настройка консоли — {stock} °C.",
"install_help_what_means": "Что это значит?",
"install_help_wont_launch": "Игра не запускается?",
install_hint_setup_exe: "Установщик открыт: следуйте его шагам, и он обновит PS5Upload на месте.",
install_path_fallback_hint: "Крайняя мера для пакета, который уже лежит на PS5, когда PS5 отказывается устанавливать его из собственного хранилища и не может получить его с этого компьютера. Используется только для неустановленной базовой игры, поэтому ничего удалить не может. Не проверено: сработало на прошивке 11.20 и отклоняется на 13.60. Если попробуете, сообщите, пожалуйста, сработало ли.",
install_path_fallback_label: "Устанавливать по пути к файлу, когда PS5 не может достучаться до этого компьютера",
"installed_fix_permissions": "Исправить права: сделать папку этой игры доступной PS5 для чтения и запуска (chmod 777)",
"installed_fix_permissions_done": "Права исправлены: у каждого файла в папке этой игры теперь 0777. Нажмите «Играть».",
"installed_fix_permissions_short": "Исправить права",
"installed_launch_homebrew_refused": "PS5 отказалась запускать эту игру (0x80940033). Сейчас консоль не запускает homebrew и игры из фейковых пакетов: перезагрузите kstuff (или перезагрузите консоль и снова выполните джейлбрейк), затем снова нажмите «Играть».",
"installed_launch_no_kstuff": "PS5 отказалась запускать эту игру (0x80940033), потому что kstuff не запущен. Без него консоль не запускает ни homebrew, ни игры из фейковых пакетов. Загрузите kstuff (автозагрузчиком или через Подключение → Настроить) и снова нажмите «Играть».",
