job_why_loading: "Загрузка…",
job_why_local_note: "Хранится только на этом компьютере. Не содержит ни адресов, ни путей к файлам, и никуда не отправляется.",
job_why_network: "Ни одно ограничение не преобладало: ни консоль, ни источник не тормозили задачу, значит, ограничением была сетевая связь.",
