job_why_slow_drive: "Передача переключилась на последовательную запись из-за медленного накопителя.",
job_why_source_starved: "Ограничено источником на {pct} %: ограничением было чтение источника (медленный диск, сетевая папка или распаковка архива на этом компьютере).",
job_why_title: "Почему было медленно?",
job_why_unmeasured: "Эта задача завершилась до того, как её удалось измерить.",
job_why_window_full: "Окно приёма заполнено {pct} %: данные отправлялись быстрее, чем консоль подтверждала их получение, при этом консоль не сообщала об ограничении ни со стороны накопителя, ни со стороны рабочих потоков. Обычно это означает медленную сеть (Wi-Fi, слабый сигнал или загруженная сеть); обычное решение — проводное подключение.",
