"pkg.reason.staged_refused": "PS5 отклонила этот пакет из собственного хранилища. До версии 6.3.1 причиной была ошибка в ps5upload; она исправлена, так что это больше не должно повторяться — дело не в файле. Если увидите это снова, установите пакет через «Стриминг и установка» с компьютера (десктопное приложение или веб-интерфейс на домашнем сервере) и отправьте нам отчёт об ошибке.",
