"pkglib.staged_install_note": "Установка из собственного хранилища PS5 (FW {fw})… Некоторые прошивки отклоняют пакеты этим способом. Если пакет отклонён, он остаётся на консоли; тогда установите его через «Стриминг и установка» с компьютера.",
