"minion_lan_hint": "Выкл.: открыть можно только в браузере самой PS5. Вкл.: телефон, планшет или компьютер в той же сети тоже смогут его открыть, а значит, любой пользователь этой сети. Включайте только дома.",
"minion_open_here": "Открыть здесь",
"minion_remove_note": "Удаление выключает Minion и стирает то, что он хранит на PS5: избранное и недавние папки в разделе «Файлы», кэш библиотеки игр и журнал геймпада. Сетевые ресурсы, читы и резервные копии остаются: ими пользуется и приложение для ПК.",
"minion_remove": "Удалить Minion с этой PS5…",
"minion_remove_title": "Удалить PS5Upload Minion?",
"minion_remove_confirm": "Его плитка на главном экране и страница исчезнут, а его собственные файлы на PS5 будут удалены. Помощник с этого момента держит его выключенным. Включить его снова можно здесь в любой момент.",
