"connection_send_payload_moved": "Нужно отправить другой payload (kstuff, etaHEN, любой .elf)? Это в разделе «Пейлоады» → «Отправить payload». Этот экран отправляет только помощника PS5Upload.",
"connection_send_payload_open": "Открыть «Отправить payload»",
"upload_elf_title": "Это payload (.elf), а не игра",
"upload_elf_body": "Загрузка лишь копирует файл. ShadowMount+ подхватывает папки игр (с eboot.bin и sce_sys) и образы игр, но никогда .elf, поэтому он не появится на главном экране. Чтобы запустить его, отправьте его загрузчику консоли. Загружать нужно homebrew-приложение в виде образа .ffpkg или .exfat либо папки с eboot.bin.",
"netdoctor.hint.below_test": "Эта загрузка идёт со скоростью {speed}, намного ниже {expected}, измеренных тестом скорости.",
"netdoctor.hint.runs_at": "Эта загрузка идёт со скоростью {speed}.",
"netdoctor.hint.cause_source": "Сдерживает не сеть, а чтение файлов на этом компьютере: USB- или жёсткий диск, сетевая папка (NAS) или распаковка архива медленнее соединения. Если сначала скопировать игру на внутренний SSD или загружать файлы архива после распаковки, скорость будет полной.",
"netdoctor.hint.cause_disk": "Сдерживает не сеть, а накопитель PS5: внешний USB-диск, почти заполненный диск или тысячи мелких файлов (каждый требует своего времени) записываются медленнее, чем доставляет соединение. Образ игры (.ffpkg или .exfat) передаётся одним файлом.",
"netdoctor.hint.cause_workers": "PS5 всё ещё записывает полученное, а не ждёт сеть. При множестве мелких файлов каждый требует своего времени; образ игры (.ffpkg или .exfat) передаётся одним файлом.",
"netdoctor.hint.cause_cap": "Сдерживает ограничение скорости загрузки (около {cap} МиБ/с, на этом экране и в настройках). Установите 0, чтобы его снять.",
"profile.np.confirm_body_v2": "np-fake-signin записывает на PS5 файлы и настройки входа в PlayStation Network для {user}. Ничего не отправляется в Sony. После этого перезапустите PS5.",
"profile.np.side_effect": "Известный побочный эффект: после этого некоторые консоли перед запуском любой игры просят «Временно отключить ограничения консоли PS5», а пункт Настройки > Пользователи и учётные записи > Другое > Выйти может остаться неактивным. Приложение сначала сохраняет на PS5 копию всего, что меняет np-fake-signin, поэтому «Отменить вход» здесь возвращает всё обратно.",
"profile.np.backing_up": "Сохраняем на PS5 копию текущих настроек учётной записи…",
"profile.np.backup_failed": "PS5 не смогла сохранить копию настроек учётной записи, поэтому np-fake-signin не запущен. Замените помощника версией из этого приложения и попробуйте снова. ({error})",
"profile.np.step_restart_v2": "Перезапустите PS5. Чтобы отменить позже, нажмите здесь «Отменить вход» и перезапустите снова.",
"profile.np.undo": "Отменить вход",
"profile.np.undo_hint": "На PS5 хранится копия настроек этой учётной записи до входа; это возвращает её.",
"profile.np.undo_confirm_title": "Отменить вход?",
"profile.np.undo_confirm_body": "Возвращает настройки и файлы {user} к состоянию до запуска np-fake-signin. После этого перезапустите PS5. Функции, которым нужна учётная запись со входом, в том числе Remote Play, могут перестать открываться до повторного входа.",
"profile.np.undoing": "Возвращаем настройки…",
"profile.np.undone": "Возвращено ({count} настроек и файлов). Перезапустите PS5, чтобы завершить.",
"profile.np.no_backup": "В этой учётной записи стоят шаблонные настройки np-fake-signin (дата рождения 1983-04-12, флаг взрослого офлайн-аккаунта выключен), а копии прежнего состояния на этой PS5 нет, поэтому приложение не может это отменить. Если PS5 теперь перед запуском игр просит временно отключить ограничения консоли: Настройки > Семья и родительский контроль > Ограничения консоли PS5 (код 0000, если вы его не меняли), и снимите там ограничения.",
