"rp_settings": "Настройки",
"rp_running_elsewhere": "«Игра» запущена на {name}",
"rp_show_here": "Показать здесь",
"rp_running_elsewhere_body": "Он был запущен из другого окна или до перезагрузки страницы и всё ещё идёт.",
"rpg_user_title": "Войдите в пользователя на PS5",
"rpg_user_body": "На консоли выберите пользователя, за которого будете играть. Оставаться у экрана никому не нужно, но вход в пользователя должен быть выполнен. Используйте пользователя без кода входа: код не даёт выполнить автоматический вход, когда консоль просыпается.",
"rpg_account_title": "Дайте этому пользователю ID аккаунта",
"rpg_account_body": "Remote Play связывается по ID аккаунта. У пользователя, связанного с PlayStation Network, он уже есть; офлайн-пользователю его нужно задать в разделе «Пользователи» выше (подойдёт любой ID; запишите его — сохранения, сделанные после этого, будут привязаны к нему).",
"rpg_signin_title": "Выполните вход аккаунта в PlayStation Network (офлайн)",
"rpg_signin_body": "PS5 разрешает Remote Play только аккаунту, вошедшему в сеть. Если собственная настройка «Remote Play» на консоли неактивна, выполните офлайн-вход ниже (в Sony ничего не отправляется), затем перезапустите PS5. Это можно отменить.",
"rpg_signin_fix": "Перейти ко входу",
"rpg_service_title": "Включите Remote Play",
"rpg_service_body": "Настройки › Система › Remote Play › Включить Remote Play. Приложение может включить его за вас, а на прошивке 10.00 и новее — ещё и разрешить для этого пользователя. Если потом «Старт» сообщает, что Remote Play выключен, включите его в настройках самой PS5: важен именно переключатель на консоли.",
"rpg_rest_title": "Разрешите выводить PS5 из режима покоя",
"rpg_rest_body": "Настройки › Система › Энергосбережение › Функции в режиме покоя: включите «Оставаться подключённым к интернету» и «Разрешить включение PS5 по сети». Без них консоль в режиме покоя нельзя разбудить, а её сеть засыпает через несколько секунд. Эти настройки есть только на самой консоли.",
"rpg_pair_title": "Сопрягите это приложение с консолью",
"rpg_pair_body": "«Подключение» › «Включить и войти» › «Настроить». Один щелчок регистрирует это приложение на PS5 (как при сопряжении приложения PS Remote Play) и хранит его ключи на этом компьютере. Они нужны для трансляции, пробуждения и входа; повторите это после сброса консоли или смены пользователя.",
"rpg_play_title": "Играть",
"rpg_play_body": "Откройте Remote Play и нажмите «Старт»: приложение разбудит консоль, если она в режиме покоя, выполнит вход и начнёт трансляцию. Играйте контроллером, подключённым к этому компьютеру, с клавиатуры или касаниями. Чтобы вместо этого использовать приложение PS Remote Play от Sony или chiaki-ng, запросите PIN ниже и введите его там.",
"rpg_play_fix": "Открыть Remote Play",
"rpg_title": "Настройка Remote Play",
"rpg_progress": "Выполнено {done} из {n} проверяемых шагов",
"rpg_on_console": "проверьте на консоли",
"rpg_trouble": "Если всё ещё не работает",
"rpg_t_start_q": "«Старт» неактивен на экране «Игра».",
"rpg_t_start_a": "Это приложение ещё не сопряжено с этой консолью: выполните шаг 6 («Подключение» › «Включить и войти» › «Настроить»).",
"rpg_t_pair_q": "При настройке сопряжения сообщается, что нет вошедшего пользователя с активированным аккаунтом.",
"rpg_t_pair_a": "Шаги 1 и 2: войдите в пользователя на PS5 и дайте ему ID аккаунта, затем повторите попытку.",
"rpg_t_grey_q": "Собственная настройка «Remote Play» на PS5 неактивна.",
"rpg_t_grey_a": "Аккаунт не вошёл в PlayStation Network. Выполните офлайн-вход (шаг 3) и перезапустите PS5.",
"rpg_t_wake_q": "Консоль не просыпается или просыпается, но остаётся на экране выбора пользователя.",
"rpg_t_wake_a": "Проверьте шаг 5 на консоли. Код входа у пользователя не даёт выполнить автоматический вход. Если консоль сбрасывали или пользователь сменился, настройте сопряжение заново (шаг 6).",
"rpg_t_black_q": "Изображение остаётся чёрным, подтормаживает или звук трещит.",
"rpg_t_black_a": "Подключите PS5 и этот компьютер кабелем или к Wi-Fi 5 GHz и попробуйте 720p или 30 fps в настройках Remote Play. Брандмауэр на этом компьютере должен разрешать приложению работу в локальной сети (Remote Play использует порты TCP и UDP 9295–9304). В браузере используйте свежий Chrome, Edge или Safari: для изображения нужен WebCodecs.",
"rpg_t_busy_q": "Сообщается, что PS5 ещё завершает прошлый сеанс или что транслируется другая консоль.",
"rpg_t_busy_a": "Транслируется одна консоль за раз, и PS5 нужно до 30 секунд после окончания сеанса. Остановите другую трансляцию, немного подождите и снова нажмите «Старт».",
"rpg_t_restrict_q": "После офлайн-входа игры просят отключить ограничения консоли.",
"rpg_t_restrict_a": "Нажмите «Отменить вход» на этой странице и перезапустите консоль или снимите ограничение в Настройки › Семья и родительский контроль › Ограничения консоли PS5 (код 0000, если вы его не меняли).",
