"rp_keys_body3": "Нажмите на картинку, чтобы играть с клавиатуры; Esc возвращает указатель. Двойной щелчок — полный экран; там короткое Esc — это Круг, а удержание Esc выходит из полного экрана. Клавиши, звук и другое — в Настройках.",
