"dump_decrypt_risk": "Расшифровка может заморозить консоль",
"dump_decrypt_risk_body": "Для расшифровки помощник ненадолго подменяет для каждого исполняемого файла часть системы, которой пользуются все программы. Если игра в этот момент читает файл, консоль может зависнуть и потребовать жёсткого выключения. Оставайтесь на стартовом экране игры, пока идёт процесс. Только прошивки до 13.60; на более новых дамп — простая копия.",
